use super::*;
#[path="../../../🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{grant,observe,drain};
use semio_framework_dsl_record::receiving::owned::{NativeIntrinsicReceiving,OwnedFieldReceiving};
fn initial()->EnergyModelSnapshot{let mut birth=super::super::genesis::EnergyModelInitialBirth::new();for _ in 0..100{if birth.ready(){break;}let g=grant(birth.demand(4096).unwrap());birth.advance(4096,g).unwrap();}let g=grant(birth.take_demand().unwrap());let(value,_)=birth.take(g).unwrap().unwrap();birth.begin_close();while !birth.terminal_is_empty(){let g=grant(birth.close_demand(4096).unwrap());birth.close_step(g).unwrap();}value}
#[test]
fn native_intrinsic_pack_source_borrows_every_original_genesis_field_and_exact_authored_schema(){let state=initial();let spec=<EnergyModelSnapshot as BorrowedDslRecord>::RECORD;let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(spec.fields.len(),1);assert_eq!(spec.fields[0].id,1);assert_eq!(spec.fields[0].key,"document");assert!(matches!(spec.fields[0].shape,BorrowedShape::Value));let mut callback=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(0,&mut callback);let(hash,h)=observe(||semio_framework_pack_record_preflight::borrowed_schema_hash(spec,&mut control).unwrap());assert_eq!(h,(0,0));assert_eq!(hash,SCHEMA_HASH);assert_eq!(hash.iter().map(|b|format!("{b:02x}")).collect::<String>(),law["schemaHash"].as_str().unwrap());let mut stack=vec![(Vec::<usize>::new(),&state as&dyn Tree)];let mut visited=0;while let Some((path,original))=stack.pop(){let mut projected=vec![0];projected.extend_from_slice(&path);let(view,h)=observe(||state.projection_view(&projected).unwrap());assert_eq!(h,(0,0));let length=match(original.canonical_tree_node().unwrap(),view){(Node::Object(a),View::IntrinsicObject(b))|(Node::Array(a),View::IntrinsicArray(b))=>{assert_eq!(a,b);a},(Node::Null,View::IntrinsicNull)=>0,(Node::String(a),View::IntrinsicText(b))=>{assert_eq!(a.as_ptr(),b.as_ptr());assert_eq!(a,b);0},(Node::F64(a),View::IntrinsicNumber(Number::Float(b)))=>{assert_eq!(a,b);0},(Node::U64(a),View::IntrinsicNumber(Number::UInt(b)))=>{assert_eq!(a,b);0},(Node::I64(a),View::IntrinsicNumber(Number::Int(b)))=>{assert_eq!(a,b);0},(Node::Bool(a),View::IntrinsicBool(b))=>{assert_eq!(a,b);0},_=>panic!("actual native Pack node kind differs")};for index in 0..length{if matches!(original.canonical_tree_node().unwrap(),Node::Object(_)){let(key,h)=observe(||state.projection_key(&projected,index).unwrap());assert_eq!(h,(0,0));assert_eq!(key,text(original.canonical_tree_key(index).unwrap()).unwrap());}let mut child=path.clone();child.push(index);stack.push((child,original.canonical_tree_child(index).unwrap()));}visited+=1;}assert!(visited>60);assert!(state.projection_view(&[1]).is_err());drain(state);}
#[test]
fn actual_native_intrinsic_record_receiver_reconstructs_the_same_empty_document_under_original_control(){let state=initial();let mut source=Some(semio_framework_dsl_record::FieldValue::Record(semio_framework_dsl_record::RecordValue{fields:[(1,semio_framework_dsl_record::FieldValue::Value(semio_framework_value::ToValue::to_value(&state)))].into_iter().collect()}));let mut receiver=NativeIntrinsicReceiving::<EnergyModelSnapshot>::default();let mut callback=|_|true;let mut control=semio_framework_value::NativeDecodeControl::new(1<<26,&mut callback);let mut construction=semio_framework_value_native_owned::native_decoding::owned::OriginalConstructionFixture;for _ in 0..100000{if receiver.is_ready(){break;}let g=grant(receiver.demands(&source,4096).unwrap());let(p,h)=observe(||control.with_construction_recipient(&mut construction,|native|receiver.step(&mut source,native,4096,g)).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));}assert!(receiver.is_ready());let mut output=None;let g=grant(semio_framework_value::RetirementDemand{copy_bytes:std::mem::size_of::<Option<EnergyModelSnapshot>>(),depth:1,..Default::default()});let(p,h)=observe(||receiver.take_into(&mut output,g).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(&state,output.as_ref().unwrap());assert!(receiver.terminal_is_empty());assert_eq!(observe(||drop(receiver)).1,(0,0));drain(output.take().unwrap());drain(state);if let Some(source)=source{drain(source);}}
